/// <summary>
/// COC for WMSArrivalOverview form CB841
/// </summary>
[ExtensionOf(formControlStr(WMSArrivalOverview, METUpdateArrival))]
final class METWHSArrivalOverview_METUpdateArrival_Extension
{ 
}

Method.Source:
/// <summary>
/// update source table arrival date time for selected records
/// </summary>
public void clicked()
{
    FormControl             formButtonControl = any2Object(this) as FormControl;
    FormDataSource          wMSArrivalOverviewTmpDS = formButtonControl.formRun().dataSource(tableStr(WMSArrivalOverviewTmp));
    MultiSelectionHelper    multiSelectionHelper = MultiSelectionHelper::construct();

    // Buffers
    WMSArrivalOverviewTmp       wMSArrivalOverviewTmpTable;
    WMSArrivalOverviewTmp       wMSArrivalOverviewTmpCursor = wMSArrivalOverviewTmpDS.cursor();
    WMSArrivalOverviewTmp       wMSArrivalOverviewTmpFind;

    PurchTable                  purchTableRecord;
    InventTransferTable         inventTransferTableRecord;
    METPurchTable               metPurchTable;
    METInventTransferTableExt   metInventTransferTableExt;

    RecId   saveRecId = wMSArrivalOverviewTmpCursor.RecId;

    multiSelectionHelper.parmDatasource(wMSArrivalOverviewTmpDS);

    next clicked();

    wMSArrivalOverviewTmpTable.setTmpData(wMSArrivalOverviewTmpCursor);

    Dialog dialog;
    DialogField dialogFieldArrivalDate;
    METArrivalDateTime arrivalDate;

    dialog = new Dialog("@MET:Updatedate");
    dialogFieldArrivalDate = dialog.addField(extendedTypeStr(METArrivalDateTime), "@MET:ArrivalDateTime");

    if (dialog.run())
    {
        arrivalDate = dialogFieldArrivalDate.value();

        wMSArrivalOverviewTmpCursor = multiSelectionHelper.getFirst();

        while (wMSArrivalOverviewTmpCursor)
        {
            select firstonly forupdate wMSArrivalOverviewTmpTable
                where wMSArrivalOverviewTmpTable.RecId == wMSArrivalOverviewTmpCursor.RecId;

            if (wMSArrivalOverviewTmpTable)
            {
                ttsbegin; 
                // Update the Temporary Table
                wMSArrivalOverviewTmpTable.METArrivalDateTime = arrivalDate;
                wMSArrivalOverviewTmpTable.doUpdate();

                // 3. OPTIMIZATION: Switch Case based on Transaction Type
                switch (wMSArrivalOverviewTmpTable.InventTransType)
                {
                    // Case A: Purchase Orders
                    case InventTransType::Purch:
                        purchTableRecord = PurchTable::find(wMSArrivalOverviewTmpTable.InventTransRefId, false);

                        if (purchTableRecord)
                        {
                            metPurchTable = METPurchTable::find(purchTableRecord.PurchId, true);
                            if (metPurchTable)
                            {
                                metPurchTable.ArrivalDateTime = arrivalDate;
                                metPurchTable.doUpdate();
                            }
                        }
                        break;

                    // Case B: Transfer Orders
                    case InventTransType::TransferOrderReceive:
                        inventTransferTableRecord = InventTransferTable::find(wMSArrivalOverviewTmpTable.InventTransRefId, false);

                        if (inventTransferTableRecord)
                        {
                            metInventTransferTableExt = METInventTransferTableExt::findByTransferId(inventTransferTableRecord.TransferId, true);
                            if (metInventTransferTableExt)
                            {
                                metInventTransferTableExt.ArrivalDateTime = arrivalDate;
                                metInventTransferTableExt.doUpdate();
                            }
                        }
                        break;
                }

                ttscommit;
            }

            wMSArrivalOverviewTmpCursor = multiSelectionHelper.getNext();
        }

        wMSArrivalOverviewTmpDS.research(true);

        if (saveRecId)
        {
            wMSArrivalOverviewTmpFind.setTmpData(wMSArrivalOverviewTmpDS.cursor());
            select firstonly wMSArrivalOverviewTmpFind
                where wMSArrivalOverviewTmpFind.RecId == saveRecId;

            if (wMSArrivalOverviewTmpFind)
            {
                wMSArrivalOverviewTmpDS.findRecord(wMSArrivalOverviewTmpFind);
            }
        }
    }
    else
    {
        info("@WAX:UpdateCancelled");
    }
}
